        LEFT JOIN pg_catalog.pg_attrdef ad
          ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
        WHERE a.attrelid=st.oid AND a.attnum>0 AND NOT a.attisdropped
      ), '[]'::jsonb) AS columns,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
