          'validated', con.convalidated
        ) ORDER BY con.contype, con.conname)
        FROM pg_catalog.pg_constraint con
        WHERE con.conrelid=st.oid AND con.contype IN ('p','u','c','f')
      ), '[]'::jsonb) AS constraints,
