        JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid
        LEFT JOIN pg_catalog.pg_constraint con ON con.conindid=i.indexrelid
        WHERE i.indrelid=st.oid AND con.oid IS NULL
      ), '[]'::jsonb) AS indexes,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'name', tg.tgname,
