y":null,"name":"termination_reason_code","notNull":false,"ordinal":20,"type":"text"},{"default":null,"identity":null,"name":"created_at","notNull":true,"ordinal":21,"type":"timestamp with time zone"},{"default":null,"identity":null,"name":"started_at","notNull":false,"ordinal":22,"type":"timestamp with time zone"},{"default":null,"identity":null,"name":"terminated_at","notNull":false,"ordinal":23,"type":"timestamp with time zone"},{"default":null,"identity":null,"name":"lease_expires_at","notNull":false,"ordinal":24,"type":"timestamp with time zone"},{"default":null,"identity":null,"name":"owner_token","notNull":false,"ordinal":25,"type":"text"},{"default":null,"identity":null,"name":"remote_session_ref","notNull":false,"ordinal":26,"type":"text"}],"constraints":[{"definition":"CHECK (distribution_mode = 'local_persistent'::text)","name":"ck_agent_sessions_1","type":"c","validated":true},{"definition":"CHECK (deployment_tier = ANY (ARRAY['development'::text, 'test'::text]))","name":"ck_agent_sessions_2","type":"c","validated":true},{"definition":"CHECK (attempt_number >= 1)","name":"ck_agent_sessions_3","type":"c","validated":true},{"definition":"CHECK (status = ANY (ARRAY['creating'::text, 'active'::text, 'terminated'::text, 'failed'::text]))","name":"ck_agent_sessions_4","type":"c","validated":true},{"definition":"CHECK (runtime_pool_id = runtime_environment_id)","name":"ck_agent_sessions_5","type":"c","validated":true},{"definition":"FOREIGN KEY (runtime_load_receipt_id) REFERENCES runtime_load_receipts(receipt_id) ON DELETE RESTRICT","name":"fk_agent_sessions_runtime_load_receipt_id_runtime_load_receipts","type":"f","validated":true},{"definition":"FOREIGN KEY (runtime_plugin_lock_id) REFERENCES deck_runtime_plugin_locks(id) ON DELETE RESTRICT","name":"fk_agent_sessions_runtime_plugin_lock_id_deck_runtim_d1f3baf217","type":"f","validated":true},{"definition":"FOREIGN KEY (workflow_run_id) REFERENCES workflow_runs(id) ON DELETE RESTRICT","name":"fk_agent_sessions