plugin_lock_digest IS DISTINCT FROM NEW.runtime_plugin_lock_digest\n    OR OLD.settings_json IS DISTINCT FROM NEW.settings_json\n    OR OLD.settings_hash IS DISTINCT FROM NEW.settings_hash\n    OR OLD.plugin_set_hash IS DISTINCT FROM NEW.plugin_set_hash\n    OR OLD.session_request_key IS DISTINCT FROM NEW.session_request_key\n    OR OLD.attempt_number IS DISTINCT FROM NEW.attempt_number\n    OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session binding is immutable';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"agent_sessions_immutable_binding"},{"definition":"CREATE TRIGGER agent_sessions_lifecycle_insert_guard BEFORE INSERT ON agent_sessions FOR EACH ROW EXECUTE FUNCTION dream_guard_agent_sessions_lifecycle_insert_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_agent_sessions_lifecycle_insert_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.status != 'creating'\n    OR NEW.started_at IS NOT NULL\n    OR NEW.terminated_at IS NOT NULL\n    OR NEW.error_code IS NOT NULL\n    OR NEW.termination_reason_code IS NOT NULL\n    OR NEW.lease_expires_at IS NULL THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'new agent session must start with a creating lease';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"agent_sessions_lifecycle_insert_guard"},{"definition":"CREATE TRIGGER agent_sessions_lifecycle_update_guard BEFORE UPDATE ON agent_sessions FOR EACH ROW EXECUTE FUNCTION dream_guard_agent_sessions_lifecycle_update_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_agent_sessions_lifecycle_update_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF (NEW.status = 'active' AND (\n    NEW.started_at IS NULL OR NEW.terminated_at IS NOT NULL\n    OR NEW.error_code IS NOT NULL OR NEW.termination_reason_code IS NOT NULL\n    ))\n    OR (NEW.status = 'terminated' AND (\n    NEW.started_at IS NULL OR NEW.terminated_at IS NULL\n    OR NEW.error_code IS NOT NULL OR NEW.termination_reason_code IS NULL\n    ))\n    OR (NEW.status = 'failed' AND (\n    NEW.terminated_at IS NULL OR NEW.error_code IS NULL\n    OR NEW.termination_reason_code IS NULL\n    )) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session lifecycle fields are inconsistent';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"agent_sessions_lifecycle_update_guard"},{"definition":"CREATE TRIGGER agent_sessions_status_guard BEFORE UPDATE OF status ON agent_sessions FOR EACH ROW EXECUTE FUNCTION dream_guard_agent_sessions_status_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_agent_sessions_status_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF OLD.status IS DISTINCT FROM NEW.status\n    AND NOT (\n    (OLD.status = 'creating' AND NEW.status IN ('active', 'failed'))\n    OR (OLD.status = 'active' AND NEW.status IN ('terminated', 'failed'))\n    ) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session transition is not allowed';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"agent_sessions_status_guard"}]},{"columns":[{"default":null,"identity":"d","name":"id","notNull":true,"ordinal":1,"type":"bigint"},{"default":null,"identity":null,"name":"user_id","notNull":true,"ordinal":2,"type":"bigint"},{"default":null,"identity":null,"name":"report_type","notNull":true,"ordinal":3,"type":"text"},{"default":null,"identity":null,"name":"report_data_json","notNull":true,"ordinal":4,"type":"text"},{"default":null,"identity":null,"name":"all_notes_text","notNull":false,"ordinal":5,"type":"text"},{"default":"now()","identity":null,"name":"created_at","notNull":false,"ordinal":6,"type":"timestamp wit