IN\n  INSERT INTO platform_users (\n    id, source, external_user_id, email, display_name, tier, status, metadata\n  ) VALUES (\n    'usr_' || md5('ink-dream:' || NEW.id::text),\n    'ink-dream',\n    NEW.id::text,\n    NEW.email,\n    NEW.display_name,\n    'free',\n    'active',\n    jsonb_build_object('managedBy', 'canonical-users')\n  )\n  ON CONFLICT (source, external_user_id) DO UPDATE\n  SET email = EXCLUDED.email,\n      display_name = EXCLUDED.display_name,\n      updated_at = NOW()\n  RETURNING id INTO billing_identity_id;\n\n  INSERT INTO billing_accounts (id, platform_user_id)\n  VALUES (\n    'acct_' || md5('canonical-user:' || billing_identity_id),\n    billing_identity_id\n  )\n  ON CONFLICT (platform_user_id) DO NOTHING;\n\n  RETURN NEW;\nEND;\n$function$\n","name":"users_sync_billing_identity"},{"definition":"CREATE TRIGGER zz_users_default_free_subscription AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION provision_default_free_subscription_after_user()","function":"CREATE OR REPLACE FUNCTION public.provision_default_free_subscription_after_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  PERFORM public.provision_default_free_subscription(NEW.id);\n  RETURN NEW;\nEND;\n$function$\n","name":"zz_users_default_free_subscription"}]},{"columns":[{"default":null,"identity":null,"name":"id","notNull":true,"ordinal":1,"type":"text"},{"default":null,"identity":null,"name":"deck_id","notNull":true,"ordinal":2,"type":"text"},{"default":null,"identity":null,"name":"name","notNull":true,"ordinal":3,"type":"text"},{"default":null,"identity":null,"name":"name_zh","notNull":false,"ordinal":4,"type":"text"},{"default":null,"identity":null,"name":"name_en","notNull":false,"ordinal":5,"type":"text"},{"default":null,"identity":null,"name":"system_prompt","notNull":true,"ordinal":6,"type":"text"},{"default":null,"identity":null,"name":"icon","notNull":false,"ordinal":7,"type":"text"},{"d