FOR EACH ROW EXECUTE FUNCTION "dream_guard_agent_sessions_lifecycle_update_guard"()$dream_ddl_116$;
    EXECUTE $dream_ddl_117$CREATE FUNCTION "dream_guard_agent_sessions_status_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status
    AND NOT (
    (OLD.status = 'creating' AND NEW.status IN ('active', 'failed'))
    OR (OLD.status = 'active' AND NEW.status IN ('terminated', 'failed'))
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session transition is not allowed';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
