ATE INDEX idx_workflow_runs_deck_plugin ON public.workflow_runs USING btree (deck_plugin_id, deck_plugin_version)","name":"idx_workflow_runs_deck_plugin","valid":true},{"definition":"CREATE INDEX idx_workflow_runs_idempotency ON public.workflow_runs USING btree (workspace_id, created_by, idempotency_key)","name":"idx_workflow_runs_idempotency","valid":true},{"definition":"CREATE INDEX idx_workflow_runs_retry ON public.workflow_runs USING btree (retry_of_run_id)","name":"idx_workflow_runs_retry","valid":true},{"definition":"CREATE INDEX idx_workflow_runs_source_voice_thread ON public.workflow_runs USING btree (source_voice_thread_id)","name":"idx_workflow_runs_source_voice_thread","valid":true},{"definition":"CREATE INDEX idx_workflow_runs_status ON public.workflow_runs USING btree (status)","name":"idx_workflow_runs_status","valid":true}],"name":"workflow_runs","triggers":[{"definition":"CREATE TRIGGER workflow_runs_immutable_provenance BEFORE UPDATE ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_immutable_provenance()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_immutable_provenance()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF OLD.id IS DISTINCT FROM NEW.id\n    OR OLD.workspace_id IS DISTINCT FROM NEW.workspace_id\n    OR OLD.deck_plugin_id IS DISTINCT FROM NEW.deck_plugin_id\n    OR OLD.deck_plugin_version IS DISTINCT FROM NEW.deck_plugin_version\n    OR OLD.workflow_definition_ref IS DISTINCT FROM NEW.workflow_definition_ref\n    OR OLD.deck_runtime_snapshot_id IS DISTINCT FROM NEW.deck_runtime_snapshot_id\n    OR OLD.retry_of_run_id IS DISTINCT FROM NEW.retry_of_run_id\n    OR OLD.deck_plugin_manifest_hash IS DISTINCT FROM NEW.deck_plugin_manifest_hash\n    OR OLD.deck_plugin_binding_id IS DISTINCT FROM NEW.deck_plugin_binding_id\n    OR OLD.binding_revision IS DISTINCT FROM NEW.binding_revision\n    OR OLD.runtime_plugin_lock_id IS DISTINCT FROM NEW.runtime_plugin_lock_id\n    OR OLD.workflow_preflight_id IS DISTINCT FROM NEW.workflow_preflight_id\n    OR OLD.source_voice_thread_id IS DISTINCT FROM NEW.source_voice_thread_id\n    OR OLD.idempotency_key IS DISTINCT FROM NEW.idempotency_key\n    OR OLD.input_hash IS DISTINCT FROM NEW.input_hash\n    OR OLD.semantic_fingerprint IS DISTINCT FROM NEW.semantic_fingerprint\n    OR OLD.created_by IS DISTINCT FROM NEW.created_by\n    OR OLD.created_at IS DISTINCT FROM NEW.created_at\n    OR (\n    OLD.runtime_load_receipt_id IS DISTINCT FROM NEW.runtime_load_receipt_id\n    AND NOT (\n    OLD.runtime_load_receipt_id IS NULL\n    AND NEW.runtime_load_receipt_id IS NOT NULL\n    AND OLD.status = 'queued'\n    AND NEW.status = 'running'\n    )\n    ) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow run provenance is immutable';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_immutable_provenance"},{"definition":"CREATE TRIGGER workflow_runs_joint_session_binding_guard BEFORE UPDATE ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_joint_session_binding_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_joint_session_binding_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF (NEW.runtime_load_receipt_id IS NULL) != (NEW.agent_session_id IS NULL)\n    OR (\n    OLD.runtime_load_receipt_id IS NULL\n    AND OLD.agent_session_id IS NULL\n    AND NEW.runtime_load_receipt_id IS NOT NULL\n    AND NOT (OLD.status = 'queued' AND NEW.status = 'running')\n    )\n    OR (\n    OLD.runtime_load_receipt_id IS NOT NULL\n    AND (\n    OLD.runtime_load_receipt_id IS DISTINCT FROM NEW.runtime_load_receipt_id\n    OR OLD.agent_session_id IS DISTINCT FROM NEW.agent_session_id\n    )\n    )\n    OR (\n    NEW.status IN (\n    'running', 'output_validating', 'pending_review', 'confirmed',\n    'rejected', 'continuing', 'completed'\n    )\n    AND NEW.runtime_load_receipt_id IS NULL\n    )\n    OR (\n    NEW.status IN ('preflight', 'queued')\n    AND NEW.runtime_load_receipt_id IS NOT NULL\n    )\n    OR (\n    NEW.agent_session_id IS NOT NULL\n    AND (\n    NEW.agent_session_id = NEW.source_voice_thread_id\n    OR NEW.agent_session_id = NEW.source_message_id\n    )\n    )\n    OR (\n    NEW.agent_session_id IS NOT NULL\n    AND OLD.agent_session_id IS NULL\n    AND NOT EXISTS (\n    SELECT 1 FROM agent_sessions AS session\n    WHERE session.agent_session_id = NEW.agent_session_id\n    AND session.workflow_run_id = NEW.id\n    AND session.runtime_load_receipt_id = NEW.runtime_load_receipt_id\n    AND session.runtime_plugin_lock_id = NEW.runtime_plugin_lock_id\n    AND session.status = 'active'\n    )\n    ) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow run receipt and session binding is invalid';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_joint_session_binding_guard"},{"definition":"CREATE TRIGGER workflow_runs_runtime_receipt_binding_guard BEFORE UPDATE OF runtime_load_receipt_id ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_runtime_receipt_binding_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_runtime_receipt_binding_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.runtime_load_receipt_id IS NOT NULL\n    AND OLD.runtime_load_receipt_id IS DISTINCT FROM NEW.runtime_load_receipt_id\n    AND NOT EXISTS (\n    SELECT 1\n    FROM runtime_load_receipts AS receipt\n    WHERE receipt.receipt_id = NEW.runtime_load_receipt_id\n    AND receipt.workflow_run_id = NEW.id\n    ) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'runtime load receipt is missing or bound to another run';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_runtime_receipt_binding_guard"},{"definition":"CREATE TRIGGER workflow_runs_status_version_guard BEFORE UPDATE ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_status_version_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_status_version_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF (\n    OLD.status IS DISTINCT FROM NEW.status\n    AND NEW.status_version != OLD.status_version + 1\n    ) OR (\n    OLD.status IS NOT DISTINCT FROM NEW.status\n    AND NEW.status_version != OLD.status_version\n    ) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow run status_version mismatch';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_status_version_guard"},{"definition":"CREATE TRIGGER workflow_runs_voice_source_immutable BEFORE UPDATE ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_voice_source_immutable()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_voice_source_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF OLD.source_voice_thread_id IS DISTINCT FROM NEW.source_voice_thread_id\n    OR OLD.source_message_id IS DISTINCT FROM NEW.source_message_id\n    OR OLD.source_message_time IS DISTINCT FROM NEW.source_message_time THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow run Voice source is immutable';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_voice_source_immutable"},{"definition":"CREATE TRIGGER workflow_runs_voice_source_insert_guard BEFORE INSERT ON workflow_runs FOR EACH ROW EXECUTE FUNCTION dream_guard_workflow_runs_voice_source_insert_guard()","function":"CREATE OR REPLACE FUNCTION public.dream_guard_workflow_runs_voice_source_insert_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF num_nonnulls(NEW.source_voice_thread_id, NEW.source_message_id, NEW.source_message_time) NOT IN (0, 3) THEN\n    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'Voice source requires thread, message, and time';\n  END IF;\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","name":"workflow_runs_voice_source_insert_guard"}]}]}$dream_final_contract$::jsonb
  THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='DREAM_SCHEMA_POSTFLIGHT_MISMATCH';
  END IF;
END
$dream_cutover_postflight$;
